def decide(recipient_reputation, round_num, my_history):
    # Use shorter history window (last 8 rounds instead of 10)
    history_window = my_history[-8:] if len(my_history) >= 8 else my_history
    recent_coops = sum(1 for record in history_window if record.get('action') == 'cooperate')
