    my_recent_coop_rate = recent_coops / max(total_recent, 1)

    # Dynamic cooperation threshold based on round and own history (different thresholds)
    if round_num <= 3:
        threshold = -0.7  # Even more cooperative early in game
    elif my_recent_coop_rate >= 0.8:
