    # Stronger reputation-based decision with different thresholds
    if recipient_reputation > threshold:
        return True
    elif recipient_reputation < -0.5:
        return False

    # Random cooperation that decreases more gradually (different decay pattern)
    random_coop_prob = max(0.15, 0.6 - (round_num - 5) * 0.02) if round_num > 5 else 0.6
    return random.random() < random_coop_prob

